#[derive(Clone, Copy, Debug)]
enum KiehlRoomWarpStep {
    Start,
    OnTouch,
    OnEnable,
    OnTimer30000,
    OnInit,
}

fn kiehl_room_warp_run(ctx: &Ctx, mut step: KiehlRoomWarpStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            KiehlRoomWarpStep::Start => {
                step = KiehlRoomWarpStep::OnTouch;
                continue 'machine;
            }
            KiehlRoomWarpStep::OnTouch => {
                ctx.call(Function::Warp, vec![Val::from("kh_kiehl01"), Val::from(10), Val::from(31)])?;
                return Err(Stop::End);
            }
            KiehlRoomWarpStep::OnEnable => {
                ctx.call(Function::InitNpcTimer, vec![])?;
                ctx.call(Function::NpcSpecialEffect, vec![ctx.constant("EF_SUMMONSLAVE")?])?;
                return Err(Stop::End);
            }
            KiehlRoomWarpStep::OnTimer30000 => {
                ctx.call(Function::StopNpcTimer, vec![])?;
                ctx.call(Function::NpcSpecialEffect, vec![ctx.constant("EF_SUMMONSLAVE")?])?;
                ctx.call(Function::DisableNpc, vec![Val::from("Kiehl_Room_Warp")])?;
                return Err(Stop::End);
            }
            KiehlRoomWarpStep::OnInit => {
                ctx.call(Function::DisableNpc, vec![Val::from("Kiehl_Room_Warp")])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn kiehl_room_warp(ctx: &Ctx) -> Script {
    kiehl_room_warp_run(ctx, KiehlRoomWarpStep::Start, Vec::new()).map(|_| ())
}

