#[derive(Clone, Copy, Debug)]
enum KiehlRoomTrapStep {
    Start,
    OnTouch,
    OnTimer300000,
    OnTimer600000,
    OnTimer900000,
    OnTimer1200000,
    OnGlobalTimerOff,
}

fn kiehl_room_trap_run(ctx: &Ctx, mut step: KiehlRoomTrapStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            KiehlRoomTrapStep::Start => {
                return Err(Stop::End);
            }
            KiehlRoomTrapStep::OnTouch => {
                if ctx.var(".khtrapsprung").get()?.number()? < 1 {
                    ctx.var(".khtrapsprung").set(Val::from(1))?;
                    ctx.var("$@khquestbusy").set(Val::from(1))?;
                    ctx.call(Function::InitNpcTimer, vec![])?;
                    ctx.call(
                        Function::Monster,
                        vec![
                            Val::from("kh_kiehl02"),
                            Val::from(47),
                            Val::from(13),
                            Val::from("Aliot"),
                            Val::from(1740),
                            Val::from(1),
                        ],
                    )?;
                    ctx.call(
                        Function::Monster,
                        vec![
                            Val::from("kh_kiehl02"),
                            Val::from(45),
                            Val::from(13),
                            Val::from("Alicel"),
                            Val::from(1739),
                            Val::from(1),
                        ],
                    )?;
                    ctx.call(
                        Function::Monster,
                        vec![
                            Val::from("kh_kiehl02"),
                            Val::from(49),
                            Val::from(13),
                            Val::from("Constant"),
                            Val::from(1745),
                            Val::from(1),
                        ],
                    )?;
                    ctx.call(
                        Function::Monster,
                        vec![
                            Val::from("kh_kiehl02"),
                            Val::from(51),
                            Val::from(13),
                            Val::from("Aliot"),
                            Val::from(1740),
                            Val::from(1),
                        ],
                    )?;
                    ctx.call(
                        Function::Monster,
                        vec![
                            Val::from("kh_kiehl02"),
                            Val::from(53),
                            Val::from(13),
                            Val::from("Alicel"),
                            Val::from(1739),
                            Val::from(1),
                        ],
                    )?;
                    ctx.call(
                        Function::Monster,
                        vec![
                            Val::from("kh_kiehl02"),
                            Val::from(49),
                            Val::from(13),
                            Val::from("Constant"),
                            Val::from(1745),
                            Val::from(1),
                        ],
                    )?;
                }
                return Err(Stop::End);
            }
            KiehlRoomTrapStep::OnTimer300000 => {
                step = KiehlRoomTrapStep::OnTimer600000;
                continue 'machine;
            }
            KiehlRoomTrapStep::OnTimer600000 => {
                step = KiehlRoomTrapStep::OnTimer900000;
                continue 'machine;
            }
            KiehlRoomTrapStep::OnTimer900000 => {
                if ctx.call(Function::GetMapUsers, vec![Val::from("kh_kiehl02")])? == 0 {
                    ctx.call(Function::DoNpcEvent, vec![Val::from("KiehlRoom::OnReset")])?;
                    ctx.call(Function::StopNpcTimer, vec![])?;
                }
                return Err(Stop::End);
            }
            KiehlRoomTrapStep::OnTimer1200000 => {
                ctx.call(Function::DoNpcEvent, vec![Val::from("KiehlRoom::OnReset")])?;
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            KiehlRoomTrapStep::OnGlobalTimerOff => {
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn kiehl_room_trap(ctx: &Ctx) -> Script {
    kiehl_room_trap_run(ctx, KiehlRoomTrapStep::Start, Vec::new()).map(|_| ())
}

