#[derive(Clone, Copy, Debug)]
enum KiehlRoomExitStep {
    Start,
    OnTouch,
    OnEnable,
    OnInit,
}

fn kiehl_room_exit_run(ctx: &Ctx, mut step: KiehlRoomExitStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            KiehlRoomExitStep::Start => {
                step = KiehlRoomExitStep::OnTouch;
                continue 'machine;
            }
            KiehlRoomExitStep::OnTouch => {
                if ctx.call(Function::GetMapUsers, vec![Val::from("kh_kiehl02")])?.number()? < 1 {
                    ctx.call(Function::DoNpcEvent, vec![Val::from("KiehlRoom::OnReset")])?;
                }
                ctx.call(Function::Warp, vec![Val::from("lighthalzen"), Val::from(193), Val::from(200)])?;
                return Err(Stop::End);
            }
            KiehlRoomExitStep::OnEnable => {
                ctx.call(Function::NpcSpecialEffect, vec![ctx.constant("EF_SUMMONSLAVE")?])?;
                return Err(Stop::End);
            }
            KiehlRoomExitStep::OnInit => {
                ctx.call(Function::DisableNpc, vec![Val::from("Kiehl_Room_Exit")])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn kiehl_room_exit(ctx: &Ctx) -> Script {
    kiehl_room_exit_run(ctx, KiehlRoomExitStep::Start, Vec::new()).map(|_| ())
}

pub fn kiehl_room_exit_ontouch(ctx: &Ctx) -> Script {
    kiehl_room_exit_run(ctx, KiehlRoomExitStep::OnTouch, Vec::new()).map(|_| ())
}

pub fn kiehl_room_exit_onenable(ctx: &Ctx) -> Script {
    kiehl_room_exit_run(ctx, KiehlRoomExitStep::OnEnable, Vec::new()).map(|_| ())
}

pub fn kiehl_room_exit_oninit(ctx: &Ctx) -> Script {
    kiehl_room_exit_run(ctx, KiehlRoomExitStep::OnInit, Vec::new()).map(|_| ())
}
